      /* NOTIFICATION BAR */
      function NotifBar() {
        const { showNotifBar, setShowNotifBar, toast } = useContext(Ctx);
        if (!showNotifBar) return null;
        const enable = async () => {
          if ("Notification" in window) {
            const p = await Notification.requestPermission();
            if (p === "granted") {
              new Notification("CIRQL Notifications ON 🎉", {
                body: "You will get alerts for new campus listings!",
              });
              setShowNotifBar(false);
            } else setShowNotifBar(false);
          } else {
            toast("Notifications not supported in this browser", "warning");
            setShowNotifBar(false);
          }
        };
        return (
          <div className="notif-bar">
            <div className="notif-text">
              🔔 <span className="notif-long">Never miss a deal — </span>Enable
              notifications for new campus listings
            </div>
            <button className="notif-enable-btn" onClick={enable}>
              Enable Now
            </button>
            <div className="notif-x" onClick={() => setShowNotifBar(false)}>
              ×
            </div>
          </div>
        );
      }

