      /* LOGIN MODAL */
      function LoginModal() {
        const { modal, setModal, login } = useContext(Ctx);
        const [mode, setMode] = useState("login");
        const [form, setForm] = useState({ name: "", email: "", pass: "" });
        const [errs, setErrs] = useState({});
        const [loading, setLoading] = useState(false);
        const [hint, setHint] = useState("");
        useEffect(() => {
          if (form.email.includes("@")) {
            const d = form.email.split("@")[1] || "";
            let c = "";
            for (const k in COLLEGE_MAP) {
              if (d.includes(k)) {
                c = COLLEGE_MAP[k];
                break;
              }
            }
            if (!c && d.includes(".")) {
              const p = d.split(".");
              c = p[0].charAt(0).toUpperCase() + p[0].slice(1) + " University";
            }
            setHint(c);
          } else setHint("");
        }, [form.email]);
        if (modal !== "login") return null;
        const submit = async () => {
          const e = {};
          if (mode === "register" && !form.name.trim())
            e.name = "Name is required";
          if (!form.email.includes("@")) e.email = "Valid email required";
          if (form.pass.length < 6) e.pass = "Minimum 6 characters";
          if (Object.keys(e).length) {
            setErrs(e);
            return;
          }
          setLoading(true);
          await new Promise((r) => setTimeout(r, 700));
          login(form.name || form.email.split("@")[0], form.email);
          setLoading(false);
          setForm({ name: "", email: "", pass: "" });
          setErrs({});
        };
        return (
          <div className="overlay" onClick={() => setModal(null)}>
            <div className="modal" onClick={(e) => e.stopPropagation()}>
              <div className="modal-header">
                <div>
                  <div className="modal-title">
                    {mode === "login" ? "Welcome back 👋" : "Join CIRQL 🎓"}
                  </div>
                  <div className="modal-subtitle">
                    {mode === "login"
                      ? "Log in to your campus account"
                      : "Create your campus marketplace account"}
                  </div>
                </div>
                <button className="modal-close" onClick={() => setModal(null)}>
                  ×
                </button>
              </div>
              <div className="modal-body">
                <div className="tab-group">
                  {["login", "register"].map((m) => (
                    <button
                      key={m}
                      className={`tab-btn${mode === m ? " active" : ""}`}
                      onClick={() => setMode(m)}
                    >
                      {m === "login" ? "Login" : "Sign Up"}
                    </button>
                  ))}
                </div>
                {mode === "register" && (
                  <div className="form-group">
                    <label className="form-label">Full Name</label>
                    <input
                      className={`form-input${errs.name ? " err" : ""}`}
                      placeholder="Ravi Sharma"
                      value={form.name}
                      onChange={(e) =>
                        setForm((f) => ({ ...f, name: e.target.value }))
                      }
                    />
                    {errs.name && <div className="form-err">{errs.name}</div>}
                  </div>
                )}
                <div className="form-group">
                  <label className="form-label">College Email</label>
                  <input
                    className={`form-input${errs.email ? " err" : ""}`}
                    type="email"
                    placeholder="you@college.edu"
                    value={form.email}
                    onChange={(e) =>
                      setForm((f) => ({ ...f, email: e.target.value }))
                    }
                  />
                  {errs.email && <div className="form-err">{errs.email}</div>}
                  {hint && (
                    <div className="college-hint">✅ {hint} detected</div>
                  )}
                </div>
                <div className="form-group">
                  <label className="form-label">Password</label>
                  <input
                    className={`form-input${errs.pass ? " err" : ""}`}
                    type="password"
                    placeholder="••••••••"
                    value={form.pass}
                    onChange={(e) =>
                      setForm((f) => ({ ...f, pass: e.target.value }))
                    }
                  />
                  {errs.pass && <div className="form-err">{errs.pass}</div>}
                </div>
                <button
                  className="btn-primary"
                  onClick={submit}
                  disabled={loading}
                  style={{ marginTop: 4 }}
                >
                  {loading
                    ? "Please wait…"
                    : mode === "login"
                      ? "Log In →"
                      : "Create Account →"}
                </button>
                <div className="link-text">
                  {mode === "login" ? (
                    <>
                      Don't have an account?{" "}
                      <a onClick={() => setMode("register")}>Sign up</a>
                    </>
                  ) : (
                    <>
                      Already have one?{" "}
                      <a onClick={() => setMode("login")}>Log in</a>
                    </>
                  )}
                </div>
              </div>
            </div>
          </div>
        );
      }

      /* POST MODAL */
      function PostModal() {
        const { modal, setModal, postItem } = useContext(Ctx);
        const [form, setForm] = useState({
          title: "",
          price: "",
          cat: "Books & Notes",
          cond: "Good",
          type: "sell",
          desc: "",
        });
        const [errs, setErrs] = useState({});
        const [loading, setLoading] = useState(false);
        if (modal !== "post") return null;
        const submit = async () => {
          const e = {};
          if (!form.title.trim()) e.title = "Title required";
          if (form.type !== "give" && !form.price && form.price !== "0")
            e.price = "Price required";
          if (!form.desc.trim()) e.desc = "Description required";
          if (Object.keys(e).length) {
            setErrs(e);
            return;
          }
          setLoading(true);
          await new Promise((r) => setTimeout(r, 600));
          const emap = {
            "Books & Notes": "📚",
            Electronics: "💻",
            Vehicles: "🛵",
            "Hostel Essentials": "🏠",
            Clothing: "👕",
            Services: "🛠",
          };
          postItem({
            ...form,
            price: form.type === "give" ? 0 : Number(form.price),
            emoji: emap[form.cat] || "📦",
          });
          setLoading(false);
          setForm({
            title: "",
            price: "",
            cat: "Books & Notes",
            cond: "Good",
            type: "sell",
            desc: "",
          });
          setErrs({});
        };
        return (
          <div className="overlay" onClick={() => setModal(null)}>
            <div
              className="modal modal-lg"
              onClick={(e) => e.stopPropagation()}
            >
              <div className="modal-header">
                <div>
                  <div className="modal-title">Post a Listing 📦</div>
                  <div className="modal-subtitle">
                    Sell, rent, or give away to your campus community
                  </div>
                </div>
                <button className="modal-close" onClick={() => setModal(null)}>
                  ×
                </button>
              </div>
              <div className="modal-body">
                <div className="tab-group">
                  {[
                    { v: "sell", l: "Sell" },
                    { v: "rent", l: "Rent Out" },
                    { v: "give", l: "Give Away 🆓" },
                  ].map((t) => (
                    <button
                      key={t.v}
                      className={`tab-btn${form.type === t.v ? " active" : ""}`}
                      onClick={() => setForm((f) => ({ ...f, type: t.v }))}
                    >
                      {t.l}
                    </button>
                  ))}
                </div>
                <div className="form-group">
                  <label className="form-label">Listing Title</label>
                  <input
                    className={`form-input${errs.title ? " err" : ""}`}
                    placeholder="e.g. MacBook Air M1, Physics Textbook…"
                    value={form.title}
                    onChange={(e) =>
                      setForm((f) => ({ ...f, title: e.target.value }))
                    }
                  />
                  {errs.title && <div className="form-err">{errs.title}</div>}
                </div>
                <div className="form-row-2">
                  <div className="form-group" style={{ marginBottom: 0 }}>
                    <label className="form-label">Category</label>
                    <select
                      className="form-select"
                      value={form.cat}
                      onChange={(e) =>
                        setForm((f) => ({ ...f, cat: e.target.value }))
                      }
                    >
                      {[
                        "Books & Notes",
                        "Electronics",
                        "Vehicles",
                        "Hostel Essentials",
                        "Clothing",
                        "Services",
                      ].map((c) => (
                        <option key={c}>{c}</option>
                      ))}
                    </select>
                  </div>
                  <div className="form-group" style={{ marginBottom: 0 }}>
                    <label className="form-label">Condition</label>
                    <select
                      className="form-select"
                      value={form.cond}
                      onChange={(e) =>
                        setForm((f) => ({ ...f, cond: e.target.value }))
                      }
                    >
                      {["Like New", "Good", "Fair", "Poor"].map((c) => (
                        <option key={c}>{c}</option>
                      ))}
                    </select>
                  </div>
                </div>
                {form.type !== "give" && (
                  <div className="form-group" style={{ marginTop: 18 }}>
                    <label className="form-label">
                      {form.type === "rent"
                        ? "Rent Price (per day)"
                        : "Selling Price"}
                    </label>
                    <div className="form-prefix-wrap">
                      <span className="form-prefix">₹</span>
                      <input
                        className={`form-input${errs.price ? " err" : ""}`}
                        type="number"
                        placeholder="0"
                        value={form.price}
                        onChange={(e) =>
                          setForm((f) => ({ ...f, price: e.target.value }))
                        }
                      />
                    </div>
                    {errs.price && <div className="form-err">{errs.price}</div>}
                  </div>
                )}
                <div
                  className="form-group"
                  style={{ marginTop: form.type === "give" ? 18 : 0 }}
                >
                  <label className="form-label">Description</label>
                  <textarea
                    className={`form-textarea${errs.desc ? " err" : ""}`}
                    placeholder="Describe the item — condition, specs, pickup details…"
                    rows={3}
                    value={form.desc}
                    onChange={(e) =>
                      setForm((f) => ({ ...f, desc: e.target.value }))
                    }
                  />
                  {errs.desc && <div className="form-err">{errs.desc}</div>}
                  <div className="form-hint">
                    Be clear about condition and pickup/handover arrangements.
                  </div>
                </div>
                <button
                  className="btn-primary"
                  onClick={submit}
                  disabled={loading}
                >
                  {loading ? "Posting…" : "🚀 Publish Listing"}
                </button>
              </div>
            </div>
          </div>
        );
      }

      /* DETAIL MODAL */
      function DetailModal() {
        const {
          modal,
          setModal,
          selectedItem: item,
          user,
          wishlist,
          toggleWish,
          addCart,
          cart,
          setModal: openM,
        } = useContext(Ctx);
        const [tab, setTab] = useState("desc");
        const [msg, setMsg] = useState("");
        const [chat, setChat] = useState([
          {
            from: "seller",
            text: "Hi! Yes, the item is still available 😊",
            time: "10:23 AM",
          },
        ]);
        if (modal !== "detail" || !item) return null;
        const inWish = wishlist.includes(item.id);
        const inCart = cart.some((c) => c.id === item.id);
        const fmt =
          item.price === 0 ? "Free" : "₹" + item.price.toLocaleString("en-IN");
        const send = () => {
          if (!msg.trim()) return;
          setChat((h) => [...h, { from: "me", text: msg.trim(), time: "Now" }]);
          setMsg("");
          setTimeout(
            () =>
              setChat((h) => [
                ...h,
                {
                  from: "seller",
                  text: "Sounds good! Let's meet near the main canteen tomorrow at noon.",
                  time: "Just now",
                },
              ]),
            900,
          );
        };
        return (
          <div className="overlay" onClick={() => setModal(null)}>
            <div
              className="modal modal-lg"
              style={{ maxWidth: 720 }}
              onClick={(e) => e.stopPropagation()}
            >
              <div className="modal-header">
                <div>
                  <div className="modal-title" style={{ fontSize: 17 }}>
                    {item.title}
                  </div>
                  <div className="modal-subtitle">
                    {item.college} · Posted {item.time} · {item.views} views
                  </div>
                </div>
                <button className="modal-close" onClick={() => setModal(null)}>
                  ×
                </button>
              </div>
              <div className="modal-body">
                <div className="detail-grid">
                  <div>
                    <div className="detail-img-main">{item.emoji}</div>
                  </div>
                  <div className="detail-info">
                    <div className="detail-price-wrap">
                      <div
                        className={`detail-price${item.price === 0 ? " free" : ""}`}
                        style={{
                          color:
                            item.price === 0 ? "var(--green)" : "var(--black)",
                        }}
                      >
                        {fmt}
                      </div>
                      {item.type === "rent" && item.price > 0 && (
                        <span
                          style={{
                            fontSize: 14,
                            color: "var(--gray-500)",
                            fontWeight: 500,
                          }}
                        >
                          /day
                        </span>
                      )}
                    </div>
                    <div className="detail-tags-row">
                      <span className="detail-tag">📂 {item.cat}</span>
                      <span className="detail-tag">✨ {item.cond}</span>
                      <span className="detail-tag">👁 {item.views}</span>
                      <span className="detail-tag">♥ {item.saves}</span>
                      {item.type === "rent" && (
                        <span
                          className="detail-tag"
                          style={{
                            background: "var(--black)",
                            color: "var(--yellow)",
                            borderColor: "var(--black)",
                          }}
                        >
                          RENT
                        </span>
                      )}
                    </div>
                    <div className="seller-block">
                      <div className="seller-av">{item.init}</div>
                      <div className="seller-info">
                        <div className="seller-name">{item.seller}</div>
                        <div className="seller-sub">{item.college}</div>
                      </div>
                      <div className="online-dot" title="Online" />
                    </div>
                    <div style={{ display: "flex", gap: 8 }}>
                      <button
                        className={`btn-add-cart${inCart ? " in-cart" : ""}`}
                        style={{
                          flex: 1,
                          height: 44,
                          borderRadius: "var(--r-full)",
                          fontSize: 14,
                        }}
                        onClick={() => {
                          if (!user) {
                            openM("login");
                            setModal("login");
                            return;
                          }
                          addCart(item);
                        }}
                        disabled={inCart}
                      >
                        {inCart ? "✓ In Cart" : "🛒 Add to Cart"}
                      </button>
                      <button
                        onClick={() => toggleWish(item.id)}
                        style={{
                          width: 44,
                          height: 44,
                          border: "1.5px solid var(--gray-200)",
                          borderRadius: "var(--r-full)",
                          background: "var(--white)",
                          fontSize: 20,
                          cursor: "pointer",
                          display: "flex",
                          alignItems: "center",
                          justifyContent: "center",
                          transition: "all .15s",
                        }}
                      >
                        <span style={{ color: inWish ? "#dc2626" : "#ccc" }}>
                          {inWish ? "♥" : "♡"}
                        </span>
                      </button>
                    </div>
                  </div>
                </div>
                <div className="modal-divider" />
                <div className="detail-tabs">
                  {["desc", "chat"].map((t) => (
                    <button
                      key={t}
                      className={`detail-tab${tab === t ? " active" : ""}`}
                      onClick={() => setTab(t)}
                    >
                      {t === "desc" ? "Description" : "💬 Chat with Seller"}
                    </button>
                  ))}
                </div>
                {tab === "desc" && (
                  <div className="detail-desc">{item.desc}</div>
                )}
                {tab === "chat" &&
                  (user ? (
                    <div className="chat-box">
                      <div className="chat-msgs">
                        {chat.map((m, i) => (
                          <div
                            key={i}
                            className={`bubble ${m.from === "me" ? "mine" : "theirs"}`}
                          >
                            {m.text}
                            <div className="bubble-time">{m.time}</div>
                          </div>
                        ))}
                      </div>
                      <div className="chat-input-row">
                        <input
                          className="chat-input"
                          placeholder="Type a message…"
                          value={msg}
                          onChange={(e) => setMsg(e.target.value)}
                          onKeyDown={(e) => e.key === "Enter" && send()}
                        />
                        <button className="chat-send-btn" onClick={send}>
                          <svg
                            width="14"
                            height="14"
                            viewBox="0 0 24 24"
                            fill="none"
                            stroke="currentColor"
                            strokeWidth="2.5"
                          >
                            <path d="M22 2L11 13M22 2L15 22l-4-9-9-4 20-7z" />
                          </svg>
                        </button>
                      </div>
                    </div>
                  ) : (
                    <div style={{ textAlign: "center", padding: "28px 0" }}>
                      <div
                        style={{ fontSize: 32, marginBottom: 12, opacity: 0.3 }}
                      >
                        💬
                      </div>
                      <p
                        style={{
                          fontSize: 14.5,
                          color: "var(--gray-500)",
                          marginBottom: 16,
                        }}
                      >
                        Login to chat with the seller
                      </p>
                      <button
                        className="btn-primary"
                        style={{
                          width: "auto",
                          padding: "0 28px",
                          height: 42,
                          borderRadius: "var(--r-full)",
                        }}
                        onClick={() => {
                          openM("login");
                          setModal("login");
                        }}
                      >
                        Login to Chat
                      </button>
                    </div>
                  ))}
              </div>
            </div>
          </div>
        );
      }

      /* NEWSLETTER */
      function Newsletter() {
        const { newsletterDone, setNewsletterDone, toast } = useContext(Ctx);
        const [email, setEmail] = useState("");
        const sub = () => {
          if (!email.includes("@")) {
            toast("Enter a valid email", "error");
            return;
          }
          setNewsletterDone(true);
          toast("Subscribed! 🎉", "success");
        };
        return (
          <div className="newsletter">
            <div className="newsletter-inner">
              <div className="newsletter-left">
                <h2>
                  Stay up to date
                  <br />
                  about our latest offers
                </h2>
              </div>
              <div className="newsletter-right">
                {newsletterDone ? (
                  <div
                    style={{
                      textAlign: "center",
                      padding: "20px 0",
                      color: "#4ade80",
                      fontWeight: 700,
                      fontSize: 16,
                    }}
                  >
                    ✓ You're subscribed! 🎉
                  </div>
                ) : (
                  <div className="newsletter-form">
                    <div className="newsletter-input-wrap">
                      <span className="newsletter-input-icon">
                        <svg
                          width="16"
                          height="16"
                          viewBox="0 0 24 24"
                          fill="none"
                          stroke="currentColor"
                          strokeWidth="2"
                        >
                          <rect x="2" y="4" width="20" height="16" rx="2" />
                          <path d="M22 7l-10 7L2 7" />
                        </svg>
                      </span>
                      <input
                        className="newsletter-email-input"
                        type="email"
                        placeholder="Enter your email address"
                        value={email}
                        onChange={(e) => setEmail(e.target.value)}
                        onKeyDown={(e) => e.key === "Enter" && sub()}
                      />
                    </div>
                    <button className="newsletter-btn" onClick={sub}>
                      Subscribe to Newsletter
                    </button>
                    <div className="newsletter-note">
                      No spam. Only real campus deals and updates.
                    </div>
                  </div>
                )}
              </div>
            </div>
          </div>
        );
      }

