      /* TOAST */
      function Toasts() {
        const { toasts } = useContext(Ctx);
        return (
          <div className="toast-stack">
            {toasts.map((t) => (
              <div key={t.id} className={`toast ${t.type}`}>
                {t.msg}
              </div>
            ))}
          </div>
        );
      }

      /* APP */
      function App() {
        const { page, user, modal, setModal } = useContext(Ctx);
        const renderPage = () => {
          switch (page) {
            case "cart":
              return <CartPage />;
            case "wishlist":
              return <WishlistPage />;
            case "profile":
              return <ProfilePage />;
            default:
              return <Home />;
          }
        };
        return (
          <div>
            <Topbar />
            <Navbar />
            <NotifBar />
            <main>{renderPage()}</main>
            {page === "home" && <Newsletter />}
            <Footer />
            {user && page === "home" && (
              <button className="fab" onClick={() => setModal("post")}>
                <svg
                  width="16"
                  height="16"
                  viewBox="0 0 24 24"
                  fill="none"
                  stroke="currentColor"
                  strokeWidth="2.5"
                >
                  <line x1="12" y1="5" x2="12" y2="19" />
                  <line x1="5" y1="12" x2="19" y2="12" />
                </svg>
                Post Item
              </button>
            )}
            <LoginModal />
            <PostModal />
            <DetailModal />
            <Toasts />
          </div>
        );
      }

      ReactDOM.createRoot(document.getElementById("root")).render(
        <Provider>
          <App />
        </Provider>,
      );
    